#include "file_commands.h"
#include "conversation_activity.h"
#include "file_transfer.h"
#include "transcript.h"
#include <stdio.h>
#include <string.h>
static const contact*find_ai(const contact_book*book,const char*name){const contact*c=contact_book_find(book,name);return c&&c->role==CONTACT_AI?c:NULL;}
int file_command_handle(const char*line,network_socket socket,const contact*sender,const service_config*config,const contact_book*contacts,int has_turn){char target_name[COUNCIL_NAME_LENGTH],sender_name[COUNCIL_NAME_LENGTH],name[COUNCIL_FILE_NAME],digest[65],stored[1024],reply[128],event[1400];unsigned long long parsed_size;uint64_t size;const contact*target;int received;if(!strncmp(line,"FILE ",5)){if(sender->role!=CONTACT_HUMAN){network_send(socket,"ERROR HUMAN_FILES_ONLY\n");return 1;}if(!has_turn){network_send(socket,"ERROR NOT_YOUR_TURN\n");return 1;}if(sscanf(line+5,"%63s %127s %llu %64s",target_name,name,&parsed_size,digest)!=4){network_send(socket,"ERROR FILE_HEADER\n");return 1;}size=(uint64_t)parsed_size;if(size>config->max_file_bytes){network_send(socket,"ERROR FILE_TOO_LARGE\n");return 1;}target=find_ai(contacts,target_name);if(!target){network_send(socket,"ERROR TARGET_UNKNOWN\n");return 1;}if(network_send(socket,"READY\n"))return 1;received=file_transfer_receive_stream(socket,config->files_directory,name,size,digest,stored,sizeof(stored));if(received==-2){network_send(socket,"ERROR FILE_DIGEST\n");return 1;}if(received){network_send(socket,"ERROR FILE_STORE\n");return 1;}if(file_transfer_forward(target,config->name,sender->name,stored,name,size,digest,reply,sizeof(reply))){snprintf(event,sizeof(event),"%s %s retained:%s",target_name,name,stored);transcript_append(config->transcript_path,sender->name,"file-pending",event);network_send(socket,"ERROR TARGET_OFFLINE\n");return 1;}snprintf(event,sizeof(event),"%s %s stored:%s",target_name,name,stored);transcript_append(config->transcript_path,sender->name,"file",event);conversation_activity_mark(config->activity_path);network_send(socket,"STORED\n");return 1;}if(!strncmp(line,"STORE ",6)){if(sender->role!=CONTACT_AI){network_send(socket,"ERROR AI_STORE_ONLY\n");return 1;}if(sscanf(line+6,"%63s %127s %llu %64s",sender_name,name,&parsed_size,digest)!=4){network_send(socket,"ERROR FILE_HEADER\n");return 1;}size=(uint64_t)parsed_size;if(size>config->max_file_bytes){network_send(socket,"ERROR FILE_TOO_LARGE\n");return 1;}if(network_send(socket,"READY\n"))return 1;received=file_transfer_receive_stream(socket,config->files_directory,name,size,digest,stored,sizeof(stored));if(received==-2){network_send(socket,"ERROR FILE_DIGEST\n");return 1;}if(received){network_send(socket,"ERROR FILE_STORE\n");return 1;}snprintf(event,sizeof(event),"%s %s stored:%s",sender_name,name,stored);transcript_append(config->inbox_path,sender->name,"file",event);conversation_activity_mark(config->activity_path);network_send(socket,"STORED\n");return 1;}return 0;}
